update merchant_customer_note
set hidden = 1, deleted_by = #{actorMemberId}, deleted_at = now(),
    hidden_request_id = #{requestId}, version = version + 1
where merchant_id = #{merchantId} and merchant_scope_version = 2
  and member_id = #{customerMemberId}
  and id = #{noteId} and hidden = 0 and version = #{expectedVersion}
